"use strict";(()=>{var n=class{getRawDigits(i){return i.replace(/\D/g,"")}isAllDigitsSame(i){let t=this.getRawDigits(i);return/^(\d)\1{10}$/.test(t)}mask(i){let t=this.getRawDigits(i);return t=t.replace(/^(\d{3})(\d)/,"$1.$2"),t=t.replace(/^(\d{3})\.(\d{3})(\d)/,"$1.$2.$3"),t=t.replace(/(\d{3})(\d{1,2})$/,"$1-$2"),t}isRequired(i){let t=this.getRawDigits(i);return!t||t.trim()===""?"Esse campo \xE9 obrigat\xF3rio":!0}checkLength(i){return this.getRawDigits(i).length!==11?"O CPF deve possuir 11 d\xEDgitos":!0}calculateCheckDigit(i,t){let r=0;for(let s=0;s<t.length;s++)r+=parseInt(i.charAt(s),10)*t[s];let e=r%11;return e<2?0:11-e}checkFirstDigit(i){let t=this.getRawDigits(i);if(this.isAllDigitsSame(t))return"CPF inv\xE1lido (d\xEDgitos repetidos)";let r=this.calculateCheckDigit(t,[10,9,8,7,6,5,4,3,2]);return parseInt(t.charAt(9),10)!==r?"CPF inv\xE1lido (1\xBA d\xEDgito verificador incorreto)":!0}checkSecondDigit(i){let t=this.getRawDigits(i);if(this.isAllDigitsSame(t))return"CPF inv\xE1lido (d\xEDgitos repetidos)";let r=this.calculateCheckDigit(t,[11,10,9,8,7,6,5,4,3,2]);return parseInt(t.charAt(10),10)!==r?"CPF inv\xE1lido (2\xBA d\xEDgito verificador incorreto)":!0}validate(i){let r=[this.checkLength.bind(this),this.checkFirstDigit.bind(this),this.checkSecondDigit.bind(this)].map(e=>e(i)).filter(e=>e!==!0);return r.length===0?!0:r}};})();
